-- Spec 0009: countries and couriers are data the app cannot run without. 0003 and
-- 0004 only created their tables, so a database built from migrations alone (not
-- reloaded from the seed) had none: every checkout refused and "Deliver to" was
-- empty. This adds the launch rows from data/*.json without touching any that exist.
INSERT INTO "afrideal"."countries" ("id", "data") VALUES ('BW', $lane${"id":"BW","code":"BW","name":"Botswana","currency":"BWP","towns":["Gaborone","Francistown","Molepolole","Maun","Serowe","Selebi-Phikwe","Kanye","Lobatse","Palapye","Mahalapye"],"buyer_currency":"BWP","payment_methods":[{"name":"Visa / Mastercard","blurb":"Pay by card through our secure gateway.","method":"DPO_PAY"},{"name":"Bank transfer","blurb":"Pay from your bank; we start sourcing once it reaches us, usually 1 to 3 working days.","method":"EFT"},{"name":"Orange Money","blurb":"Mobile money from a Botswana number.","method":"ORANGE_MONEY"}],"active":true,"sort_order":1}$lane$::jsonb) ON CONFLICT ("id") DO NOTHING;
--> statement-breakpoint
