-- Runners from before spec 0009 have a city but no country or towns. They were all
-- in Botswana; their own city is the town they serve until someone edits it.
UPDATE "afrideal"."runners" SET "data" = "data" || jsonb_build_object('country', 'BW') WHERE NOT ("data" ? 'country');
--> statement-breakpoint
UPDATE "afrideal"."runners" SET "data" = "data" || jsonb_build_object('towns', jsonb_build_array("data"->>'city')) WHERE NOT ("data" ? 'towns') AND "data" ? 'city';
